#!/usr/bin/env python3
import os, re, glob
NINJA = os.environ.get("NINJA", "/tmp/llvm22_build/build.ninja")
SRCROOT = os.environ.get("LLVM_SRCROOT", "/tmp/llvm22")
LIBDIR = "external/apache2/llvm/lib"
pat = re.compile(r"CMakeFiles/(?:obj\.)?([A-Za-z0-9_]+)\.dir/[^ ]*\.o: \S+ "
    + re.escape(SRCROOT) + r"/(llvm|clang)/(\S+\.(?:cpp|c))(?:\s|$|\|)")
src_info = []
for line in open(NINJA):
    if "CMakeFiles/" not in line or ".o: " not in line: continue
    m = pat.search(line)
    if m: src_info.append((m.group(1), m.group(2), m.group(3), os.path.dirname(m.group(3))))
owners=[]; reach={}
ppat=re.compile(r"^\.PATH:\s*\$\{(LLVM_SRCDIR|CLANG_SRCDIR)\}/(\S+)")
for mk in glob.glob(f"{LIBDIR}/*/Makefile"):
    has=False
    for line in open(mk):
        m=ppat.match(line)
        if m:
            comp="llvm" if m.group(1)=="LLVM_SRCDIR" else "clang"
            owners.append((comp,m.group(2).rstrip("/"),mk)); has=True
    if has: reach[mk]=True
assigned={mk:[] for mk in reach}; unowned={}
for tgt,comp,rel,sdir in src_info:
    best=None
    for (c,d,mk) in owners:
        if c!=comp: continue
        if sdir==d or sdir.startswith(d+"/"):
            if best is None or len(d)>len(best[0]): best=(d,mk)
    if best: assigned[best[1]].append(rel[len(best[0])+1:])
    else:
        u=unowned.setdefault(tgt,{'comp':comp,'dirs':set(),'srcs':[]})
        u['dirs'].add(sdir); u['srcs'].append((sdir,rel))
def srcs_block(entries):
    entries=sorted(set(entries))
    out=["SRCS+=\t"+entries[0]+(" \\\n" if len(entries)>1 else "\n")]
    for e in entries[1:-1]: out.append("\t"+e+" \\\n")
    if len(entries)>1: out.append("\t"+entries[-1]+"\n")
    return out
changed=0
for mk,entries in assigned.items():
    if not entries: continue
    lines=open(mk).readlines(); out=[]; i=0; inserted=False
    while i<len(lines):
        l=lines[i]
        if re.match(r"^SRCS\s*\+?=", l):
            j=i
            while lines[j].rstrip("\n").endswith("\\"): j+=1
            block="".join(lines[i:j+1])
            if re.search(r"\.(cpp|c|inc)\b", block):
                if not inserted: out.extend(srcs_block(entries)); inserted=True
                i=j+1; continue
        out.append(l); i+=1
    if not inserted:
        for k,l in enumerate(out):
            if l.startswith(".include <bsd."): out[k:k]=srcs_block(entries)+["\n"]; break
    open(mk,"w").writelines(out); changed+=1
SRCDIRVAR={"llvm":"LLVM_SRCDIR","clang":"CLANG_SRCDIR"}; created=[]
for tgt,u in sorted(unowned.items()):
    comp=u['comp']; d=f"{LIBDIR}/lib{tgt}"; os.makedirs(d,exist_ok=True)
    root=min(u['dirs'],key=len)
    entries=[rel[len(root)+1:] for sdir,rel in u['srcs']]
    body=["#\tGenerated by regen-srcs-from-cmake.py for LLVM 22\n\n",
          f"LIB=\t{tgt}\n\n",".include <bsd.init.mk>\n\n",
          f".PATH: ${{{SRCDIRVAR[comp]}}}/{root}\n\n"]
    body.extend(srcs_block(entries)); body.append("\n.include <bsd.lib.mk>\n")
    open(f"{d}/Makefile","w").writelines(body); created.append("lib"+tgt)
print(f"sources={len(src_info)} existing_rewritten={changed} new_libs={len(created)}")
print("NEW:", " ".join(sorted(created)))
